# typed: true
# frozen_string_literal: true

module UserLists
  class MenuContentComponent < ApplicationComponent
    FILTERABLE_THRESHOLD = 10

    # repository - The Repository which may be added or removed from the current user's UserLists.
    # lists_applied_set - a UserList::AppliedSet generated by UserList.applied_to that contains the user's lists,
    #   pre-grouped by whether or not they contain the repository.
    def initialize(repository:, lists_applied_set:)
      @repository = repository
      @lists_applied_set = lists_applied_set
    end

    private

    attr_reader :repository

    def render?
      logged_in? && repository.present? && !@lists_applied_set.nil?
    end

    def show_suggested_lists?
      @lists_applied_set.empty? && !has_created_lists?
    end

    def show_blank_slate?
      @lists_applied_set.empty? && has_created_lists?
    end

    memoize def has_created_lists?
      current_user.has_created_lists?
    end

    memoize def can_create_lists?
      current_user.can_create_lists?
    end

    def with_each_list
      if show_suggested_lists?
        UserList.with_each_default_suggestion do |suggested_name, suggested_name_html|
          yield "list_names[]", suggested_name, suggested_name_html, false
        end
      else
        @lists_applied_set.containing(@repository.id).each do |list|
          yield "list_ids[]", list.id, list.name_html, true
        end
        @lists_applied_set.not_containing(@repository.id).each do |list|
          yield "list_ids[]", list.id, list.name_html, false
        end
      end
    end

    def update_url
      repo_user_lists_path(@repository.owner_display_login, @repository)
    end

    def batch_update_url
      user_list_menu_batches_path(current_user)
    end

    def view_lists_path
      user_path(current_user, params: { tab: :stars })
    end

    def filterable?
      @lists_applied_set.size > FILTERABLE_THRESHOLD
    end
  end
end
